import React from 'react';

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'danger';
  loading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ children, variant = 'primary', loading, style, disabled, ...props }) => {
  const bg = variant === 'danger' ? '#dc2626' : variant === 'secondary' ? '#334155' : variant === 'outline' ? 'transparent' : '#2563eb';
  return (
    <button
      disabled={disabled || loading}
      style={{
        background: bg,
        color: '#fff',
        border: variant === 'outline' ? '1px solid #475569' : 'none',
        borderRadius: '8px',
        padding: '10px 18px',
        fontWeight: 600,
        cursor: disabled || loading ? 'not-allowed' : 'pointer',
        opacity: disabled || loading ? 0.65 : 1,
        ...style,
      }}
      {...props}
    >
      {loading ? 'Processing...' : children}
    </button>
  );
};

export default Button;
